    "status": "Targeting ~mid-2027",
    "valuation": "$12.7B valuation after $2B Series G (2026) \u00b7 ~$540M projected revenue",
    "note": "Defense AI/autonomy company (V-BAT drone, Hivemind autonomy software). Just raised a $2B Series G; analysts see it approaching IPO-ready metrics with ~80% YoY growth, with a filing expected by mid-2027."
